/// Explains why `danger()` must come after `setup()`.
fn run<'a>(x: &'a str) -> usize {
    // danger(); was here once
    setup();
    let s = "a } in a string";
    let r = r#"raw { "quoted" }"#;
    let c = '}';
    let d = '\\';
    let q = '\'';
    danger();
    s.len() + r.len() + x.len() + c.len_utf8() + d.len_utf8() + q.len_utf8()
}

